  if(!obj(item)||!txt(item.description,500)||
     !txt(item.quantity,40)||!/^\d{1,7}(?:\.\d{1,3})?$/u.test(item.quantity)||
     !(Number(item.quantity)>0&&Number(item.quantity)<=1000000)||
     !txt(item.unit,20)||!['unit','bag','box','kg','g','l','ml','m','m2','m3','roll','pack']
      .includes(item.unit))
