  deliveryNote:raw.deliveryNote as string|null,items,
  ...(typeof raw.requestedPayment==='string'&&typeof raw.requestedVat==='string'?
   {requestedPayment:raw.requestedPayment,requestedVat:raw.requestedVat}:{})};
