  }catch{/* Bloqueo, timeout o estado remoto incierto: NUNCA reintentar. */}
  try{await finalize(valid?'api_accepted':'uncertain',messageId)}
  catch{return result('requiere_conciliacion',claimed,accepted,uncertain)}
