type DbResponse={data:unknown;error:unknown};
/** Solo ejecuta una RPC cuya implementación no puede despachar.
 * No exponer request_id, catálogo ni token de WhatsApp en web o logs.
 */
export async function guardarRondaSombraMvp221(
 prepared:ResultadoPuenteMvp221,
 rpc:(name:string,params:Params)=>Promise<DbResponse>
):Promise<Readonly<{estado:'guardado'|'ya_existia'|'rechazado';
 motivo:string;articulos:number;matches:number}>>{
 const error=(motivo:string)=>({estado:'rechazado' as const,
  motivo,articulos:0,matches:0});
 if(prepared?.estado!=='plan_sql_listo'||!prepared.params||
    typeof rpc!=='function')return error('plan_no_preparado');
 try{
  // V2-21: solo RPC V2 aislada. Nunca modificar/ejecutar M221 histórico.
  const result=await rpc('cotironda_piloto_v2_shadow_prepare_d013',
   prepared.params);
  if(result.error!==null&&result.error!==undefined)
   return error('sql_no_disponible');
  const d=result.data;
  if(!d||typeof d!=='object'||Array.isArray(d))
   return error('sql_no_conciliado');
  const body=d as Record<string,unknown>;
  if(body.state==='already_staged')
   return {estado:'ya_existia',motivo:'idempotencia_por_mensaje',
    articulos:0,matches:0};
  const expected=prepared.params;
  const lines=expected.p_items.length;
  const matches=expected.p_destinos.reduce(
   (sum,d)=>sum+d.correspondencias.length,0);
  if(body.state!=='shadow_staged'||body.items_staged!==lines||
     body.matches_staged!==matches||body.invitations_sent!==0||
     body.outbox_sent!==0)return error('sql_resultado_incoherente');
  return {estado:'guardado',motivo:'ronda_sombra_verificada',
   articulos:lines,matches};
 }catch{return error('sql_no_disponible')}
}

/** Cotironda V2 — adaptador de conversación para la IA Central.
 * NO envía, NO crea fuentes sintéticas, NO reemplaza originales.
 * Solo texto por ahora; los adjuntos requieren su extractor autenticado.
 */
export type FuenteConversacionV2=Readonly<{
 message_hmac:string;source_sha256:string;kind:string;nonce:string;ciphertext:string;
}>;
export type TramoConversacionV2=Readonly<{
 messageHmac:string;sha256:string;inicio:number;fin:number;
}>;
export type ContextoConversacionV2=Readonly<{
 texto:string;tramos:readonly TramoConversacionV2[];
}>;
const HASH=/^[a-f0-9]{64}$/u;
export async function abrirConversacionTextoV2(args:{
 chatHmac:string;fuentes:readonly FuenteConversacionV2[];
 descifrar:(nonce:string,ciphertext:string,aad:string)=>Promise<string>;
 sha256:(text:string)=>Promise<string>;
}):Promise<ContextoConversacionV2>{
 if(!HASH.test(args.chatHmac)||!Array.isArray(args.fuentes)||!args.fuentes.length)
  throw Error('conversation_source_invalid');
 const seen=new Set<string>();const tramos:TramoConversacionV2[]=[];
 let texto='';
 for(const f of args.fuentes){
  if(!f||!HASH.test(f.message_hmac)||!HASH.test(f.source_sha256)||
    seen.has(f.message_hmac)||typeof f.nonce!=='string'||typeof f.ciphertext!=='string')
   throw Error('conversation_source_invalid');
  if(f.kind!=='text')throw Error('conversation_attachment_requires_verified_extractor');
  seen.add(f.message_hmac);
  const literal=await args.descifrar(f.nonce,f.ciphertext,
   args.chatHmac+'|'+f.message_hmac+'|text');
  if(typeof literal!=='string'||!literal.trim()||await args.sha256(literal)!==f.source_sha256)
   throw Error('conversation_source_sha_mismatch');
  if(texto)texto+='\n\n';
  const inicio=texto.length;texto+=literal;
  tramos.push({messageHmac:f.message_hmac,sha256:f.source_sha256,inicio,fin:texto.length});
 }
 return {texto,tramos:Object.freeze(tramos)};
}
/** Preserva la referencia a la fuente de cada cita; no atribuir un tramo
 * fabricado al mensaje original. La IA puede relacionar fragmentos, pero
 * las citas de producto/cantidad por separado deben conservar sus fuentes. */
export function evidenciaConversacionV2(contexto:ContextoConversacionV2,
 inicio:number,fin:number,evidencia:string):TramoConversacionV2|null{
 if(!Number.isSafeInteger(inicio)||!Number.isSafeInteger(fin)||inicio<0||fin<=inicio||
    contexto.texto.slice(inicio,fin)!==evidencia)return null;
 const t=contexto.tramos.find(x=>inicio>=x.inicio&&fin<=x.fin);
 return t?{...t,inicio:inicio-t.inicio,fin:fin-t.inicio}:null;
}
export type CondicionSolicitadaV2=Readonly<{
 valor:string;origen:'predeterminado'|'comprador';evidencia:TramoConversacionV2|null;
}>;
export type CitaCondicionV2=Readonly<{inicio:number;fin:number;literal:string}>;
const CONTACT=/(?:https?:\/\/|www\.|[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}|(?:\+?\d[\s.-]?){9,}|\b(?:whatsapp|tel[eé]fono|celular|cuit|cuil|correo|email)\b)/iu;
/** La MISMA IA identifica las citas de pago/IVA en la lectura del comprador.
 * Ausencia explícita (null) activa cada default de forma independiente.
 * No usar esto para presupuestos del proveedor. Una cita inválida NO se
 * convierte en default: se devuelve error para autocorrección de IA. */
export function condicionesSolicitudV2(contexto:ContextoConversacionV2,
 pago:CitaCondicionV2|null,iva:CitaCondicionV2|null):
 Readonly<{pago:CondicionSolicitadaV2;iva:CondicionSolicitadaV2}>{
 const resolve=(c:CitaCondicionV2|null,valor:string):CondicionSolicitadaV2=>{
  if(c===null)return {valor,origen:'predeterminado',evidencia:null};
  if(!c||typeof c.literal!=='string'||c.literal.length>120||
     !c.literal.trim()||CONTACT.test(c.literal)||/[\u0000-\u001f\u007f]/u.test(c.literal))
   throw Error('conversation_condition_invalid');
  const evidencia=evidenciaConversacionV2(contexto,c.inicio,c.fin,c.literal);
  if(!evidencia)throw Error('conversation_condition_source_invalid');
  return {valor:c.literal.trim(),origen:'comprador',evidencia};
 };
 return {pago:resolve(pago,'Contado efectivo'),iva:resolve(iva,'Precios sin IVA')};
}

/** V2 conversation worker. Reuses the only IA reader, matcher and SQL bridge.
 * Entry point must be an authenticated internal tick, not a client request.
 * Text-only candidate: mixed attachments remain queued for verified extraction.
 */
import {abrirConversacionTextoV2,condicionesSolicitudV2,type FuenteConversacionV2,type ContextoConversacionV2} from './buyer-conversation-context-v2.ts';
import {instrumentoOpenAiMvp264} from './ai-central-usage-mvp264.ts';
import {planificarMensajeAutenticadoMvp220} from '../../../src/domain/ia-central/planificador-piloto-v2-d013.ts';
import {armarPreparacionSombraMvp221} from '../../../src/domain/ia-central/puente-sql-rondas-v2-d013.ts';
import {codigoRevisionSemanticaMvp286,codigoRevisionPuenteV2D013} from './ai-central-buyer-v2-d013.ts';
type Rpc=(name:string,params:Record<string,unknown>)=>Promise<{data:unknown;error:unknown}>;
type Model='gpt-6-luna'|'gpt-6.1-sol';
const HASH=/^[a-f0-9]{64}$/u;
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iu;
const obj=(x:unknown):x is Record<string,unknown>=>x!==null&&typeof x==='object'&&!Array.isArray(x);
export type ConversationIo=Readonly<{
 rpc:Rpc;apiKey:string;model:Model;
 decrypt:(nonce:string,ciphertext:string,aad:string)=>Promise<string>;
 sha:(value:string)=>Promise<string>;
 sendClarification:(id:string,chat:string,event:string,body:string)=>Promise<void>;
 usageFetchImpl?:typeof fetch;
 plan?:typeof planificarMensajeAutenticadoMvp220;
}>;
export async function procesarConversacionV2(chat:string,id:string,io:ConversationIo):Promise<string>{
 if(!HASH.test(chat)||!UUID.test(id))return 'invalid';
 const call=async(name:string,params:Record<string,unknown>)=>{
  const r=await io.rpc(name,params);if(r.error!=null||!obj(r.data)||typeof r.data.state!=='string')throw Error('conversation_rpc');
  return r.data;
 };
 const g=await call('cotironda_piloto_v2_conversation_claim',{p_chat_hmac:chat});
 if(g.state!=='claimed')return String(g.state);
 if(g.conversation_id!==id||typeof g.lease!=='string'||!UUID.test(g.lease)||
    typeof g.revision!=='number'||!Number.isSafeInteger(g.revision)||!Array.isArray(g.sources)||!g.sources.length)
  return 'claim_inconsistent';
 const fields={p_chat_hmac:chat,p_id:id,p_revision:g.revision,p_lease:g.lease};
 const sources=g.sources as FuenteConversacionV2[];
 const last=sources[sources.length-1]?.message_hmac;
 const first=sources[0]?.message_hmac;
 if(!HASH.test(last)||!HASH.test(first))return 'source_invalid';
 // Never silently dispatch a partial mixed-format order.
 if(sources.some(s=>s.kind!=='text')){
  const blocked=await call('cotironda_piloto_v2_conversation_decide',{...fields,p_decision:'review'});
  return blocked.state==='review'?'attachment_extractor_pending':String(blocked.state);
 }
 let context:ContextoConversacionV2;
 try{context=await abrirConversacionTextoV2({chatHmac:chat,fuentes:sources,descifrar:io.decrypt,sha256:io.sha})}
 catch{await call('cotironda_piloto_v2_conversation_decide',{...fields,p_decision:'review'});return 'source_integrity_failed'}
 const meter=await call('cotironda_piloto_v2_conversation_meter',fields);
 if(meter.state==='meter_busy'||meter.state==='stale')return String(meter.state);
