  await call('cotironda_piloto_v2_conversation_decide',{...fields,p_decision:'review'});
  return 'meter_not_available';
 }
 const finish=async(decision:'awaiting_context'|'review'|'staged',reason:string,reply?:{code:'zone'|'materials';body:string})=>{
  const r=await call('cotironda_piloto_v2_conversation_finish',{...fields,p_message_hmac:last,p_decision:decision,p_reason:reason,p_reply_code:reply?.code??null});
  if(reply&&r.reply_reserved===true&&r.state===decision)await io.sendClarification(id,chat,last,reply.body);
  return String(r.state);
 };
 try{
  let payment:{literal:string;message_hmac:string}|null=null;
  let vat:{literal:string;message_hmac:string}|null=null;
  let metaSeen=false;
  const cite=(literal:string|null)=>{
   if(literal===null)return null;
   for(const t of [...context.tramos].reverse()){
    const source=context.texto.slice(t.inicio,t.fin);const at=source.lastIndexOf(literal);
    if(at>=0)return {literal,inicio:t.inicio+at,fin:t.inicio+at+literal.length};
   }
   throw Error('condition_not_in_source');
  };
  const plan=await (io.plan??planificarMensajeAutenticadoMvp220)({
   chatHmac:chat,messageHmac:first,textoOriginal:context.texto,autenticadoPorWebhook:true,
   apiKey:io.apiKey,model:io.model,rpc:io.rpc,
   fetchImpl:instrumentoOpenAiMvp264({messageHmac:last,chatHmac:chat,role:'buyer',model:io.model,rpc:io.rpc,initialCallNo:meter.usage_call_no,fetchImpl:io.usageFetchImpl}),
   onConversacion:meta=>{
    const conditions=condicionesSolicitudV2(context,cite(meta.pago),cite(meta.iva));
    payment=conditions.pago.evidencia&&meta.pago!==null?{literal:meta.pago,message_hmac:conditions.pago.evidencia.messageHmac}:null;
    vat=conditions.iva.evidencia&&meta.iva!==null?{literal:meta.iva,message_hmac:conditions.iva.evidencia.messageHmac}:null;
    metaSeen=true;
   }
  });
  if(plan.motivo==='conversation_waiting')return finish('awaiting_context','conversation_waiting');
  if(plan.motivo==='conversation_multiple_orders')return finish('awaiting_context','conversation_multiple_orders');
  if(plan.motivo==='zona_de_entrega_faltante'||plan.motivo==='falta_localidad')
   return finish('awaiting_context','delivery_city_missing',{code:'zone',body:'¿En qué localidad se entregan los materiales?'});
  if(plan.motivo==='ia_central_solicita_aclaracion'&&plan.pregunta)
   return finish('awaiting_context','ia_central_solicita_aclaracion',{code:'materials',body:plan.pregunta});
  if(plan.estado!=='plan_validado_sin_envio'||!plan.pedido||!metaSeen)
   return finish('review',metaSeen?codigoRevisionSemanticaMvp286(plan.motivo):'conversation_metadata_missing');
  const prepared=armarPreparacionSombraMvp221({chatHmac:chat,messageHmac:first,textoOriginal:context.texto,autenticadoPorWebhook:true,plan,multifuente:true});
  if(prepared.estado!=='plan_sql_listo'||!prepared.params)
   return finish('review',codigoRevisionPuenteV2D013(prepared.motivo));
  const p=prepared.params;
  const fragments=context.tramos.map(t=>({message_hmac:t.messageHmac,text:context.texto.slice(t.inicio,t.fin)}));
  const stage=await call('cotironda_piloto_v2_conversation_stage',{p_buyer_chat_hmac:chat,p_id:id,p_revision:g.revision,p_lease:g.lease,p_fragments:fragments,p_city:p.p_city,p_items:p.p_items,p_destinos:p.p_destinos,p_payment:payment,p_vat:vat});
